// Две роли · spec: specs/location-map.md 3.2 · кейс .qa/tests/location-map/MAP-02.md
// Пузырь со счётчиком (2+ человек в одной точке) не автоматизирован — нужно 3+ аккаунта; здесь «אני» поверх одного соседа.
import { test, expect } from '../../fixtures';
import { userIdOf } from './map-helpers';
import { setupPair, teardownPair, pinOf, USER2_NAME, type Pair } from './pair-helpers';

test.describe('מסך מפת זמן אמת', () => {
  test.describe.configure({ timeout: 240_000 });
  test('зум-аут: сосед под «אני», «אני» сверху; тап «אני» → лист «בקרבתך / מהקרוב לרחוק», «סגירה»; карточка → профиль @iphone @data (#0f19c0)', async ({ asUser }) => {
    let p: Pair | undefined;
    try {
      p = await setupPair(asUser, true);
      const { free } = p;
      const me = free.getByText('אני', { exact: true });
      const pin = pinOf(free, USER2_NAME);
      await expect(me).toBeVisible();
      await expect(pin).toBeVisible();

      // Зум-аут колесом над картой, пока пин соседа не окажется под «אני» (Р5/Р6: зум-аут — точки сливаются).
      await free.mouse.move(195, 420);
      await expect
        .poll(async () => {
          await free.mouse.wheel(0, 500);
          const a = await me.boundingBox();
          const b = await pin.boundingBox();
          if (!a || !b) return Infinity;
          return Math.hypot(a.x + a.width / 2 - (b.x + b.width / 2), a.y - (b.y + b.height / 2));
        }, { timeout: 30_000, intervals: [700] })
        .toBeLessThan(40);

      // «אני» всегда видно и над чужими пинами (Р6): в точке пина соседа сверху — маркер «אני».
      const pb = (await pin.boundingBox())!;
      const topIsMe = await free.evaluate(([x, y]) => {
        const el = document.elementFromPoint(x, y);
        return !!el?.closest('.leaflet-marker-icon')?.textContent?.includes('אני');
      }, [pb.x + pb.width / 2, pb.y + pb.height / 2]);
      expect(topIsMe, '«אני» поверх пина соседа').toBe(true);

      // Тап «אני» → лист людей рядом, от ближнего к дальнему, с карточкой соседа (Р6; шит 18.04).
      await me.click();
      await expect(free.getByText(/בקרבתך\s*מהקרוב לרחוק/).or(free.getByText('מהקרוב לרחוק')).first()).toBeVisible();
      const card = free.getByRole('button', { name: `${USER2_NAME}, 56` }).filter({ hasText: 'ממך' });
      await expect(card).toBeVisible();
      await expect(card).toContainText(/\d+(\.\d)?\s*(מ׳|ק״מ) ממך/);
      // «סגירה» закрывает лист.
      await free.getByRole('button', { name: 'סגירה' }).click();
      await expect(free.getByText('מהקרוב לרחוק')).toBeHidden();

      // Снова «אני» → карточка → профиль соседа (AC 6).
      await me.click();
      await expect(card).toBeVisible();
      await card.click();
      await free.waitForURL(new RegExp(`/profile/${userIdOf('user2')}`));
      // Экран профиля соседа: имя (поверх фото) и кнопка «אהבתי».
      await expect(free.getByText(`${USER2_NAME}, 56`).first()).toBeAttached();
      await expect(free.getByRole('button', { name: 'אהבתי' })).toBeVisible();
    } finally {
      await teardownPair(p);
    }
  });
});
